import numpy as np
from math import sin,cos,pi
atoms=[]; groups={}
def add(el,r):
 atoms.append((el,np.array(r,dtype=float))); return len(atoms)
def methyl(c,parent,phase=0):
 d=np.array(c)-parent; d/=np.linalg.norm(d)
 u=np.cross(d,[0,0,1]);
 if np.linalg.norm(u)<.01:u=np.cross(d,[0,1,0])
 u/=np.linalg.norm(u); v=np.cross(d,u)
 for k in range(3):
  th=phase+2*pi*k/3
  add('H',c+1.09*(d/3+np.sqrt(8/9)*(cos(th)*u+sin(th)*v)))
add('Ti',[0,0,0]);add('Cu',[3.02,0,0]);add('Br',[5.38,0,0])
for sign,phase in [(1,pi/10),(-1,3*pi/10)]:
 center=np.array([-.82,0,sign*1.96]); n=center/np.linalg.norm(center)
 u=np.array([abs(n[2]),0,-sign*n[0]]); v=np.cross(n,u)
 ring=[]; methyls=[]
 for k in range(5):
  th=phase+2*pi*k/5; d=cos(th)*u+sin(th)*v
  c=center+1.208*d; ring.append(add('C',c))
  mc=center+(1.208+1.50)*d; methyls.append((mc,c));add('C',mc)
 for mc,c in methyls: methyl(mc,c,.4)
 groups['Cp'+str(sign)]=ring
for sign,rot in [(1,pi/3),(-1,-pi/3)]:
 a=np.array([1.57,sign*1.48,0]);b=np.array([2.69,sign*2.045,0]);add('C',a);add('C',b)
 d=(b-a)/np.linalg.norm(b-a); e0=np.array([-d[1],d[0],0]);e=cos(rot)*e0+sin(rot)*np.array([0,0,1.])
 ipso=b+1.445*d;center=ipso+1.398*d
 ring=[];methyls=[]
 for k in range(6):
  th=pi+k*pi/3; radial=cos(th)*d+sin(th)*e
  c=center+1.398*radial;ring.append(add('C',c))
  if k in [1,5]:
   mc=center+2.898*radial; add('C',mc);methyls.append((mc,c))
  elif k!=0: add('H',center+2.481*radial)
 for mc,c in methyls: methyl(mc,c,.4)
 groups['aryl'+str(sign)]=ring
with open('start.xyz','w') as f:
 f.write(f'{len(atoms)}\nCp*2Ti bis(2,6-dimethylphenylacetylide) CuBr complex\n')
 for el,p in atoms:f.write(f'{el:2s} {p[0]: .8f} {p[1]: .8f} {p[2]: .8f}\n')
print('atoms',len(atoms),'groups',groups)
# noncovalent heavy distances for inspection
for i,(s,r) in enumerate(atoms):
 if s=='H':continue
 for j,(t,q) in enumerate(atoms[:i]):
  if t!='H' and np.linalg.norm(r-q)<1.2:print('short',i+1,j+1,np.linalg.norm(r-q))
